def main():
    data=json.loads((OUT/'course.json').read_text())
    voice_count=sum(l.get('voice')=='Warm Lulu' for l in data['lessons'])
    voice_status=(f'All {voice_count} illustrated lessons use Warm Lulu narration, with brief pauses between scenes.'
                  if voice_count==len(data['lessons']) else
                  f'Warm Lulu narration is installed in {voice_count} of {len(data["lessons"])} illustrated lessons; conversion is in progress.')
    deep=json.loads((OUT/'deep-dive/preparation-validation.json').read_text())
    detailed_status=f'{deep.get("assembled_detailed_videos",0)} detailed videos use actual Resgrid screens, with chapters and captions.'
    page=HTML.replace('Detailed configuration storyboards','Watch detailed configuration videos').replace('Narrated draft lessons','Primer video drafts')
    page=page.replace('__VOICE_STATUS__',voice_status+' '+detailed_status)
    (OUT/'index.html').write_text(page.replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('<','\\u003c')))
    (OUT/'production'/'production-guide.html').write_text(GUIDE.replace('A local Firehouse 51 stack now supplies',detailed_status+' A local Firehouse 51 stack now supplies'))
    with (OUT/'settings.csv').open('w',newline='') as f:
        w=csv.writer(f);w.writerow(['id','area','lesson','label','guidance','source_default','controller','action','field','availability','source'])
        for s in data['settings']:w.writerow([s['id'],s['area'],s['lesson'],s['label'],s['help'],s['default'],s['location']['Controller'],s['location']['Action'],s['location'].get('Field'),s['availability'],s['source']['path']])
    with (OUT/'coverage.csv').open('w',newline='') as f:
        w=csv.writer(f);w.writerow(['feature_id','area','lesson','feature','release_status','controller','action','capture_status','source','docs_reference'])
        for c in data['features']:w.writerow([c['id'],c['area'],c['lesson'],c['label'],c['release_status'],c['location']['Controller'],c['location']['Action'],c['capture_status'],c['source']['path'],c['docs_url']])
    api=[]
    for p in sorted((ROOT/'Web/Resgrid.Web.Services/Controllers/v4').glob('*Controller.cs')):
        text=p.read_text();routes=re.findall(r'\[(?:Route|HttpGet|HttpPost|HttpPut|HttpPatch|HttpDelete)\(([^\n]*)\)',text)
        api.append({'source':source_ref(p),'controller_file':p.name,'declared_routes':routes,'verification':'source inventory; no runtime endpoint requests made'})
    (OUT/'production'/'api-inventory.json').write_text(json.dumps(api,indent=2)+'\n')
    (OUT/'production'/'requirements.txt').write_text('Pillow\n# FFmpeg encoder required; provide its path with --ffmpeg.\n# Warm Lulu audio sources and caption exports are included.\n# New narration can be generated in the private Descript project.\n')
    print('Library ready:',len(data['lessons']),'lessons;',len(api),'v4 API controller files indexed')

if __name__=='__main__':main()
